mapper.select:
SELECT r.RESV_NUM AS resvNum, m.USER_NICKNAME AS userNickname, r.RESV_STATUS AS resvStatus, rm.ROOM_NAME AS roomName, p.PLAN_NAME AS planName, rr.RESV_CHECK_IN AS resvCheckIn, rr.RESV_CHECK_OUT AS resvCheckOut, r.RESV_PEOPLE AS resvPeople, r.RESV_PRICE AS resvPrice FROM RESERVATION r JOIN MEMBER m ON m.USER_MAIL = r.USER_MAIL LEFT JOIN ROOM_RESERVATION rr ON rr.RESV_NUM = r.RESV_NUM AND rr.ROOM_RESV_NUM = ( SELECT MIN(rr2.ROOM_RESV_NUM) FROM ROOM_RESERVATION rr2 WHERE rr2.RESV_NUM = r.RESV_NUM ) LEFT JOIN ROOM rm ON rm.ROOM_IDX = rr.ROOM_IDX LEFT JOIN PLAN p ON p.PLAN_IDX = rr.PLAN_IDX
r.ADMIN_IDX = #{adminIdx}
ORDER BY r.RESV_NUM DESC
